import {useEffect,useState} from 'react';
import {ClipboardCheck,Loader2,RefreshCw} from 'lucide-react';
import {assignAssessment,listAssessmentDefinitions,listClientAssessments} from '../../lib/assessmentApi';

export function AssessmentCard({definition,onAssign}){return <article className="rounded-2xl border border-slate-200 bg-white p-5"><span className="text-xs font-bold uppercase tracking-wider text-blue-700">{definition.scope}</span><h3 className="mt-2 font-semibold">{definition.title}</h3><p className="mt-2 text-sm text-slate-600">{definition.description}</p><button onClick={()=>onAssign(definition)} className="mt-4 min-h-11 w-full rounded-xl bg-slate-950 px-4 font-semibold text-white">Assign assessment</button></article>}
export function AssessmentHistory({items}){return items.length?<div className="divide-y rounded-2xl border bg-white">{items.map(item=><article key={item.id} className="p-4"><div className="flex items-center justify-between gap-3"><strong>{item.title}</strong><span className="rounded-full bg-blue-50 px-2 py-1 text-xs font-bold text-blue-700">{item.status}</span></div><p className="mt-1 text-xs text-slate-500">Assigned {new Date(item.assigned_at).toLocaleDateString()}</p></article>)}</div>:<div className="rounded-2xl border border-dashed bg-white p-8 text-center"><ClipboardCheck className="mx-auto text-blue-700"/><h3 className="mt-3 font-semibold">No assessments assigned yet.</h3></div>}
export function ExternalAssessments({clients=[]}){const [definitions,setDefinitions]=useState([]);const [items,setItems]=useState([]);const [clientId,setClientId]=useState(clients[0]?.id||'');const [state,setState]=useState('loading');const [error,setError]=useState('');const load=async(id=clientId)=>{setState('loading');setError('');try{const [library,history]=await Promise.all([listAssessmentDefinitions(),id?listClientAssessments(id):Promise.resolve({items:[]})]);setDefinitions(library.items||[]);setItems(history.items||[]);setState('ready')}catch(reason){setError(reason.message||'Assessments could not load.');setState('error')}};useEffect(()=>{void load()},[]);useEffect(()=>{if(clientId)void load(clientId)},[clientId]);const assign=async definition=>{if(!clientId)return;await assignAssessment(clientId,{definition_id:definition.id});await load(clientId)};return <div className="space-y-6"><header><p className="text-xs font-bold uppercase tracking-wider text-blue-700">Governed assessments</p><h2 className="mt-2 text-3xl font-bold">Assessment library</h2><p className="mt-2 text-sm text-slate-600">Profession-appropriate, non-diagnostic reviews with tenant-scoped history.</p></header><label className="block max-w-md text-sm font-semibold">Client<select value={clientId} onChange={event=>setClientId(event.target.value)} className="mt-2 min-h-12 w-full rounded-xl border px-3"><option value="">Select client</option>{clients.map(client=><option key={client.id} value={client.id}>{client.displayName}</option>)}</select></label>{state==='loading'&&<div role="status" className="grid min-h-40 place-items-center rounded-2xl bg-white"><Loader2 className="animate-spin"/><span className="sr-only">Loading assessments</span></div>}{state==='error'&&<div role="alert" className="rounded-2xl bg-red-50 p-5 text-red-800">{error}<button onClick={()=>load()} className="ml-3 min-h-11 px-3 font-bold"><RefreshCw className="inline"/> Retry</button></div>}{state==='ready'&&<><section><h3 className="mb-3 text-lg font-semibold">Available assessments</h3><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{definitions.map(item=><AssessmentCard key={item.id} definition={item} onAssign={assign}/>)}</div></section><section><h3 className="mb-3 text-lg font-semibold">Client history</h3><AssessmentHistory items={items}/></section></>}</div>}
